import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CQdiwDJy.js";const f=JSON.parse('{"title":"Built-in tools","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/tools.md","filePath":"en/guide/tools.md","lastUpdated":1788601681000}'),d={name:"en/guide/tools.md"};function r(n,e,s,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="built-in-tools" tabindex="-1">Built-in tools <a class="header-anchor" href="#built-in-tools" aria-label="Permalink to &quot;Built-in tools&quot;">​</a></h1><p>Tau&#39;s tool layer is <strong>deterministic</strong>: every tool is a registry-driven function, AI plans may only call tools that exist in the registry, and nothing is invented at runtime. Four built-in families — read-only first, mutating operations dry-run by default.</p><h2 id="the-file-family" tabindex="-1">The file family <a class="header-anchor" href="#the-file-family" aria-label="Permalink to &quot;The file family&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th><th>Risk</th></tr></thead><tbody><tr><td><code>file.find</code></td><td>recursive glob search (prunes node_modules/.git/dist)</td><td>low</td></tr><tr><td><code>file.read</code></td><td>numbered text read (offset/limit, refuses binaries and &gt;2MB; since v0.5.0 the structured result carries the detected language)</td><td>low</td></tr><tr><td><code>file.list</code></td><td>single-directory non-recursive listing</td><td>low</td></tr><tr><td><code>file.stat</code></td><td>size / type / mtime</td><td>low</td></tr><tr><td><code>file.tree</code></td><td>depth-limited directory tree</td><td>low</td></tr><tr><td><code>file.rename</code></td><td>regex batch rename (dry-run by default)</td><td>medium</td></tr><tr><td><code>file.write</code></td><td>controlled write (overwrite/append, dry-run default, workspace-contained)</td><td>medium</td></tr></tbody></table><p><strong>There is deliberately no delete.</strong> The first-party family has no delete primitive — deleting goes through reviewed shell steps or your own hands. That is a design decision recorded in the safety model, not an omission.</p><h2 id="sys-net-text-families" tabindex="-1">sys / net / text families <a class="header-anchor" href="#sys-net-text-families" aria-label="Permalink to &quot;sys / net / text families&quot;">​</a></h2><ul><li><strong>sys</strong>: read-only system probes (processes, disk, environment).</li><li><strong>net</strong>: read-only network operations (HTTP GET and friends).</li><li><strong>text</strong>: find/count-style operations over file contents.</li></ul><p>Every tool has a CLI command (<code>tau file read</code>, …) and its full parameter schema is browsable in the WebUI Tools panel.</p><h2 id="risk-and-confirmation" tabindex="-1">Risk and confirmation <a class="header-anchor" href="#risk-and-confirmation" aria-label="Permalink to &quot;Risk and confirmation&quot;">​</a></h2><p>A tool&#39;s declared <code>risk</code> drives the execution gate: low read-only tools run directly inside a plan; medium tools (writes) default to a dry-run preview and need <code>execute: true</code>; the safety reviewer re-checks every planned write path independently (defense in depth — the reviewer only ever strengthens the tool&#39;s own checks).</p><h2 id="file-read-language-metadata-v0-5-0" tabindex="-1">file.read language metadata (v0.5.0) <a class="header-anchor" href="#file-read-language-metadata-v0-5-0" aria-label="Permalink to &quot;file.read language metadata (v0.5.0)&quot;">​</a></h2><p>The structured result now carries <code>path</code> and <code>language</code> — best-effort language detection from the file name (shiki-compatible id, honest <code>text</code> fallback). The WebUI file viewer picks its highlighter with the same detection; tool layer and frontend share one logic, kept in sync by a parity test.</p>',12)])])}const m=t(d,[["render",r]]);export{f as __pageData,m as default};
